#include <stdio.h>

void add_one(int *value) {
    if (value != NULL) ++*value;
}

int main(void) {
    int count = 4;
    add_one(&count);
    printf("%d\n", count);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

void print_values(const int *values, size_t count) {
    for (size_t i = 0; i < count; ++i) printf("%d\n", values[i]);
}

int main(void) {
    int data[] = {1, 2, 3};
    print_values(data, 3);
    return 0;
}
